INSERT OR IGNORE INTO quizzes(id,slug,category_id,title,outline,current_version,position) VALUES ('q011','les-allocations-sont-notre-premiere-depense-publique','dette','Les allocations sont notre première dépense publique','["Que comprend le mot allocations ?","Quel est le poids des retraites ?","Quelle différence entre protection sociale et aides sans emploi ?"]',NULL,10);
INSERT OR IGNORE INTO quiz_versions(quiz_id,version,body,published_at) VALUES ('q011',1,'{"title":"Les allocations sont notre première dépense publique","intro":"Avant de comparer les montants, distinguons les aides sous condition de ressources et l’ensemble de la protection sociale. Données françaises de 2024.","questions":[{"id":"q011-1","prompt":"Dans la classification de l’Insee utilisée ici, quelle dépense relève de la protection sociale ?","choices":[{"id":"a","text":"L’entretien des ambassades"},{"id":"b","text":"Les pensions de retraite"},{"id":"c","text":"L’achat de matériel militaire"},{"id":"d","text":"La construction des tribunaux"}],"correctChoiceId":"b","explanation":"Les pensions de retraite appartiennent aux dépenses de protection sociale. Cette catégorie dépasse donc les seules aides destinées aux ménages sans emploi.","nuance":"Le mot « allocations » est trop imprécis pour désigner tout ce périmètre.","sources":[{"publisher":"Insee","title":"Les dépenses publiques par fonction en 2024","url":"https://www.insee.fr/fr/statistiques/8735252","checkedAt":"2026-10-23"}]},{"id":"q011-2","prompt":"En 2024, quelle fonction représente la plus grande part des dépenses publiques dans cette publication ?","choices":[{"id":"a","text":"La protection sociale, hors santé"},{"id":"b","text":"La défense"},{"id":"c","text":"L’enseignement"},{"id":"d","text":"La protection de l’environnement"}],"correctChoiceId":"a","explanation":"La protection sociale hors santé représente environ 41 % du total en 2024, devant la santé. Le classement porte sur des fonctions de dépense.","nuance":"Ce résultat ne signifie pas que les minima sociaux représentent 41 % des dépenses.","sources":[{"publisher":"Insee","title":"Les dépenses publiques par fonction en 2024","url":"https://www.insee.fr/fr/statistiques/8735252","checkedAt":"2026-10-23"}]},{"id":"q011-3","prompt":"Pourquoi ne peut-on pas attribuer les 693 milliards d’euros de protection sociale au seul RSA ?","choices":[{"id":"a","text":"Le RSA représente exactement toutes les retraites"},{"id":"b","text":"Ce montant est le budget militaire"},{"id":"c","text":"L’Insee ne compte aucune prestation"},{"id":"d","text":"Ce montant regroupe plusieurs risques et prestations, dont les retraites"}],"correctChoiceId":"d","explanation":"Les 693 milliards couvrent un ensemble de dépenses sociales. Les attribuer à une seule allocation change le sens du chiffre.","nuance":"Pour comparer une prestation précise, il faut son propre montant et la même année de référence.","sources":[{"publisher":"Insee","title":"Les dépenses publiques par fonction en 2024","url":"https://www.insee.fr/fr/statistiques/8735252","checkedAt":"2026-10-23"}]}]}','2026-10-23T12:00:00.000Z');
