INSERT OR IGNORE INTO quiz_versions(quiz_id,version,body,published_at) VALUES ('q014',1,'{"title":"La dette vient forcément d’un excès de dépenses","intro":"Trois petits raisonnements pour distinguer recettes, dépenses et déficit. Les exemples chiffrés sont fictifs.","questions":[{"id":"q014-1","prompt":"Un budget dépense 100 et reçoit 90. Quel est son déficit ?","choices":[{"id":"a","text":"100"},{"id":"b","text":"190"},{"id":"c","text":"10"},{"id":"d","text":"90"}],"correctChoiceId":"c","explanation":"Le déficit de cet exemple est la différence entre dépenses et recettes : 100 − 90 = 10.","nuance":"Ce calcul simplifié décrit un solde annuel, pas le montant total de dette.","sources":[{"publisher":"Insee","title":"Le compte des administrations publiques en 2025","url":"https://www.insee.fr/fr/statistiques/8997691","checkedAt":"2026-10-23"}]},{"id":"q014-2","prompt":"Les dépenses restent à 100, mais les recettes passent de 90 à 85. Que devient le déficit ?","choices":[{"id":"a","text":"Il devient un excédent de 15"},{"id":"b","text":"Il augmente de 10 à 15"},{"id":"c","text":"Il reste à 10"},{"id":"d","text":"Il diminue à 5"}],"correctChoiceId":"b","explanation":"À dépenses inchangées, une diminution des recettes augmente ici le déficit : 100 − 85 = 15.","nuance":"Cet exemple ne mesure pas les effets économiques indirects d’une réforme fiscale.","sources":[{"publisher":"Insee","title":"Le compte des administrations publiques en 2025","url":"https://www.insee.fr/fr/statistiques/8997691","checkedAt":"2026-10-23"}]},{"id":"q014-3","prompt":"Quelle information faut-il examiner pour expliquer l’évolution du solde public ?","choices":[{"id":"a","text":"L’évolution des recettes et des dépenses sur la même période"},{"id":"b","text":"Uniquement le total des dépenses"},{"id":"c","text":"Uniquement le nom du gouvernement"},{"id":"d","text":"Uniquement la dette à une date"}],"correctChoiceId":"a","explanation":"Un solde dépend des deux côtés du budget. L’Insee analyse conjointement leurs évolutions pour expliquer les résultats annuels.","nuance":"Cette décomposition comptable ne suffit pas à attribuer toutes les causes à une seule décision.","sources":[{"publisher":"Insee","title":"Le compte des administrations publiques en 2025","url":"https://www.insee.fr/fr/statistiques/8997691","checkedAt":"2026-10-23"}]}]}','2026-10-23T12:00:00.000Z');
