INSERT OR IGNORE INTO quizzes(id,slug,category_id,title,outline,current_version,position) VALUES ('q016','la-moitie-des-francais-ne-paie-aucun-impot','impots','La moitié des Français ne paie aucun impôt','["De quel impôt parle-t-on ?","Un ménage non imposable paie-t-il de la TVA ?","Quelle différence entre impôts et cotisations ?"]',NULL,15);
INSERT OR IGNORE INTO quiz_versions(quiz_id,version,body,published_at) VALUES ('q016',1,'{"title":"La moitié des Français ne paie aucun impôt","intro":"« Non imposable » ne veut pas dire « aucun impôt ». Commençons par préciser le prélèvement dont on parle.","questions":[{"id":"q016-1","prompt":"Dans l’expression courante « ménage non imposable », quel impôt est généralement visé ?","choices":[{"id":"a","text":"L’impôt sur le revenu"},{"id":"b","text":"Tous les impôts possibles"},{"id":"c","text":"Uniquement la TVA"},{"id":"d","text":"Uniquement les droits de douane"}],"correctChoiceId":"a","explanation":"L’expression renvoie généralement à l’impôt sur le revenu. Elle ne signifie pas que le ménage ne supporte aucun autre impôt.","nuance":"Une statistique de foyers fiscaux n’est pas automatiquement une statistique de personnes.","sources":[{"publisher":"Service Public","title":"Calcul de l’impôt sur le revenu","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F34328","checkedAt":"2026-10-23"}]},{"id":"q016-2","prompt":"Un consommateur non imposable sur le revenu achète un produit soumis à la TVA. La TVA disparaît-elle ?","choices":[{"id":"a","text":"Oui, automatiquement à la caisse"},{"id":"b","text":"Oui, si le paiement est en espèces"},{"id":"c","text":"Oui, pour tous les achats alimentaires"},{"id":"d","text":"Non, elle reste incluse dans le prix de cet achat"}],"correctChoiceId":"d","explanation":"La TVA est liée à l’opération de consommation concernée. L’absence d’impôt sur le revenu ne l’efface pas.","nuance":"Certains produits ou opérations bénéficient de taux spécifiques ou d’exonérations.","sources":[{"publisher":"Direction générale des douanes","title":"Taxe sur la valeur ajoutée","url":"https://www.douane.gouv.fr/lexique/taxe-sur-la-valeur-ajoutee-tva","checkedAt":"2026-10-23"}]},{"id":"q016-3","prompt":"Que faut-il vérifier avant d’utiliser la phrase « la moitié ne paie pas d’impôt » ?","choices":[{"id":"a","text":"Le montant du plus gros salaire"},{"id":"b","text":"Le nombre de magasins du pays"},{"id":"c","text":"L’impôt concerné, l’année et la population comptée"},{"id":"d","text":"Uniquement la couleur du graphique"}],"correctChoiceId":"c","explanation":"Un chiffre n’est interprétable que si son périmètre est explicite. Les règles de l’impôt sur le revenu et celles de la TVA portent sur des bases différentes.","nuance":"Ce parcours ne valide aucun pourcentage : il examine la confusion entre un impôt et tous les impôts.","sources":[{"publisher":"Service Public","title":"Calcul de l’impôt sur le revenu","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F34328","checkedAt":"2026-10-23"},{"publisher":"Direction générale des douanes","title":"Taxe sur la valeur ajoutée","url":"https://www.douane.gouv.fr/lexique/taxe-sur-la-valeur-ajoutee-tva","checkedAt":"2026-10-23"}]}]}','2026-10-23T12:00:00.000Z');
UPDATE quizzes SET current_version=1 WHERE id='q016' AND current_version IS NULL;
INSERT OR IGNORE INTO quizzes(id,slug,category_id,title,outline,current_version,position) VALUES ('q017','une-augmentation-peut-faire-perdre-de-l-argent-en-changeant-de-tranche','impots','Une augmentation peut faire perdre de l’argent en changeant de tranche','["À quoi s’applique le taux marginal ?","Comment calculer l’impôt dans l’exemple ?","Quelle différence avec un effet de seuil sur une aide ?"]',NULL,16);
INSERT OR IGNORE INTO quiz_versions(quiz_id,version,body,published_at) VALUES ('q017',1,'{"title":"Une augmentation peut faire perdre de l’argent en changeant de tranche","intro":"Comprendre le principe des tranches sans le confondre avec les conditions d’attribution d’une aide.","questions":[{"id":"q017-1","prompt":"À quoi s’applique le taux marginal de l’impôt sur le revenu ?","choices":[{"id":"a","text":"À tout le patrimoine"},{"id":"b","text":"À tous les revenus depuis la naissance"},{"id":"c","text":"Au salaire de tous les membres de la famille sans distinction"},{"id":"d","text":"À la tranche la plus élevée atteinte, pas à tout le revenu"}],"correctChoiceId":"d","explanation":"Le barème est progressif par tranches. Atteindre une tranche supérieure ne fait pas passer les tranches inférieures au nouveau taux.","nuance":"Le calcul complet dépend aussi des parts, déductions et autres mécanismes fiscaux.","sources":[{"publisher":"Service Public","title":"Calcul de l’impôt sur le revenu","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F34328","checkedAt":"2026-10-23"}]},{"id":"q017-2","prompt":"Exemple simplifié : 100 € supplémentaires sont intégralement dans une tranche à 30 %. Quel impôt supplémentaire produit ce seul mécanisme ?","choices":[{"id":"a","text":"100 €"},{"id":"b","text":"Tout le salaire annuel à 30 %"},{"id":"c","text":"30 €"},{"id":"d","text":"300 €"}],"correctChoiceId":"c","explanation":"Dans cet exemple, 100 × 30 % = 30 €. Les 70 € restants ne disparaissent pas à cause du seul barème.","nuance":"On isole ici le barème : aucune cotisation ou modification de prestation n’est simulée.","sources":[{"publisher":"Service Public","title":"Calcul de l’impôt sur le revenu","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F34328","checkedAt":"2026-10-23"}]},{"id":"q017-3","prompt":"Taux moyen et taux marginal désignent-ils la même chose ?","choices":[{"id":"a","text":"Le second est une taxe locale"},{"id":"b","text":"Non : le premier rapporte l’impôt au revenu, le second concerne la dernière tranche"},{"id":"c","text":"Oui, toujours"},{"id":"d","text":"Le premier ne concerne que les entreprises"}],"correctChoiceId":"b","explanation":"Le taux moyen résume la part du revenu consacrée à cet impôt. Il peut être inférieur au taux de la dernière tranche.","nuance":"Le taux de prélèvement à la source est encore une autre notion de calcul.","sources":[{"publisher":"Service Public","title":"Calcul de l’impôt sur le revenu","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F34328","checkedAt":"2026-10-23"}]}]}','2026-10-23T12:00:00.000Z');
UPDATE quizzes SET current_version=1 WHERE id='q017' AND current_version IS NULL;
