INSERT OR IGNORE INTO quizzes(id,slug,category_id,title,outline,current_version,position) VALUES ('q019','la-tva-est-juste-puisque-tout-le-monde-paie-le-meme-taux','impots','La TVA est juste puisque tout le monde paie le même taux','["Tous les produits ont-ils le même taux ?","Quel effort représente une même dépense ?","Comment l’épargne modifie-t-elle la comparaison ?"]',NULL,18);
INSERT OR IGNORE INTO quiz_versions(quiz_id,version,body,published_at) VALUES ('q019',1,'{"title":"La TVA est juste puisque tout le monde paie le même taux","intro":"Examinons le taux appliqué à un achat et l’effort qu’il représente pour différents budgets.","questions":[{"id":"q019-1","prompt":"Tous les produits ont-ils le même taux de TVA en France métropolitaine ?","choices":[{"id":"a","text":"Les taux dépendent uniquement du salaire de l’acheteur"},{"id":"b","text":"Non, plusieurs taux et des exonérations existent"},{"id":"c","text":"Oui, tous à 20 % sans exception"},{"id":"d","text":"Oui, tous à 5,5 %"}],"correctChoiceId":"b","explanation":"Il existe un taux normal et des taux particuliers ou réduits selon les opérations. Un taux unique pour tous les produits n’est donc pas la règle.","nuance":"Les règles peuvent aussi varier selon le territoire et la date.","sources":[{"publisher":"Ministère de l’Économie","title":"TVA : les taux du quotidien","url":"https://www.economie.gouv.fr/particuliers/impots-et-fiscalite/gerer-mes-autres-impots-et-taxes/tva-quels-sont-les-taux-de-votre-quotidien","checkedAt":"2026-10-23"}]},{"id":"q019-2","prompt":"Deux personnes paient chacune 20 € de TVA. Leurs revenus sont 1 000 € et 4 000 €. Quelles parts de revenu cela représente-t-il ?","choices":[{"id":"a","text":"2 % et 0,5 %"},{"id":"b","text":"2 % et 2 %"},{"id":"c","text":"20 % et 40 %"},{"id":"d","text":"0,5 % et 2 %"}],"correctChoiceId":"a","explanation":"Le calcul est 20/1 000 et 20/4 000. Une même somme ne représente pas le même effort relatif.","nuance":"C’est un exemple arithmétique fictif, pas une estimation de leur consommation réelle.","sources":[{"publisher":"Ministère de l’Économie","title":"TVA : les taux du quotidien","url":"https://www.economie.gouv.fr/particuliers/impots-et-fiscalite/gerer-mes-autres-impots-et-taxes/tva-quels-sont-les-taux-de-votre-quotidien","checkedAt":"2026-10-23"}]},{"id":"q019-3","prompt":"Le fait qu’un taux soit identique suffit-il à conclure que l’impôt est juste ?","choices":[{"id":"a","text":"Oui, c’est une identité mathématique"},{"id":"b","text":"Oui, cela prouve que tous ont le même revenu"},{"id":"c","text":"Non, cela prouve que tous les taux doivent être supprimés"},{"id":"d","text":"Non : il faut préciser les critères de justice utilisés"}],"correctChoiceId":"d","explanation":"Le taux décrit une règle de prélèvement. Juger sa justice exige de préciser le critère : montant, part du revenu ou effets de redistribution, par exemple.","nuance":"Les sources établissent les règles ; elles ne décident pas à ta place du critère de justice.","sources":[{"publisher":"Ministère de l’Économie","title":"TVA : les taux du quotidien","url":"https://www.economie.gouv.fr/particuliers/impots-et-fiscalite/gerer-mes-autres-impots-et-taxes/tva-quels-sont-les-taux-de-votre-quotidien","checkedAt":"2026-10-23"}]}]}','2026-10-23T12:00:00.000Z');
