INSERT OR IGNORE INTO quiz_versions(quiz_id,version,body,published_at) VALUES ('q022',1,'{"title":"Être riche, c’est avoir un gros salaire","intro":"Revenu, patrimoine brut, patrimoine net : trois mesures qu’on ne peut pas utiliser indifféremment.","questions":[{"id":"q022-1","prompt":"Une maison détenue et un salaire mensuel mesurent-ils la même chose ?","choices":[{"id":"a","text":"Oui, uniquement si la maison est louée"},{"id":"b","text":"Non : une maison ne peut jamais être un patrimoine"},{"id":"c","text":"Non : un actif détenu et un flux de revenu"},{"id":"d","text":"Oui, ce sont deux salaires"}],"correctChoiceId":"c","explanation":"Le patrimoine correspond à des actifs détenus à une date. Le revenu se mesure sur une période.","nuance":"Un actif peut aussi générer un revenu, mais sa valeur et ce revenu restent distincts.","sources":[{"publisher":"Insee","title":"Patrimoine net des ménages","url":"https://www.insee.fr/fr/statistiques/5371259?sommaire=5371304","checkedAt":"2026-10-23"}]},{"id":"q022-2","prompt":"Exemple : un logement vaut 200 000 € et il reste 150 000 € d’emprunt. Quel est le patrimoine net associé, sans autre actif ni dette ?","choices":[{"id":"a","text":"150 000 €"},{"id":"b","text":"50 000 €"},{"id":"c","text":"200 000 €"},{"id":"d","text":"350 000 €"}],"correctChoiceId":"b","explanation":"Le patrimoine net retranche les dettes des actifs : 200 000 − 150 000 = 50 000 €.","nuance":"Ce calcul simplifié ignore les coûts de vente et une éventuelle variation de valeur.","sources":[{"publisher":"Insee","title":"Patrimoine net des ménages","url":"https://www.insee.fr/fr/statistiques/5371259?sommaire=5371304","checkedAt":"2026-10-23"}]},{"id":"q022-3","prompt":"Que signifie un patrimoine médian de 100 000 € dans un exemple fictif ?","choices":[{"id":"a","text":"La moitié des ménages est en dessous et la moitié au-dessus"},{"id":"b","text":"Tous les ménages possèdent 100 000 €"},{"id":"c","text":"Le ménage le plus riche possède 100 000 €"},{"id":"d","text":"Le revenu moyen vaut 100 000 €"}],"correctChoiceId":"a","explanation":"La médiane sépare la distribution en deux moitiés. Elle ne doit pas être confondue avec la moyenne.","nuance":"Une même médiane peut coexister avec des répartitions très différentes au sommet.","sources":[{"publisher":"Insee","title":"Patrimoine net des ménages","url":"https://www.insee.fr/fr/statistiques/5371259?sommaire=5371304","checkedAt":"2026-10-23"}]}]}','2026-10-23T12:00:00.000Z');
