INSERT OR IGNORE INTO quizzes(id,slug,category_id,title,outline,current_version,position) VALUES ('q029','les-dividendes-sont-une-recompense-versee-aux-salaries','entreprises','Les dividendes sont une récompense versée aux salariés','["Qui reçoit les dividendes ?","Quelle différence avec l’intéressement ?","Un salarié peut-il être actionnaire ?"]',NULL,28);
INSERT OR IGNORE INTO quiz_versions(quiz_id,version,body,published_at) VALUES ('q029',1,'{"title":"Les dividendes sont une récompense versée aux salariés","intro":"Distinguer rémunération du travail et distribution aux détenteurs du capital.","questions":[{"id":"q029-1","prompt":"À quel titre reçoit-on un dividende ?","choices":[{"id":"a","text":"Automatiquement comme salarié"},{"id":"b","text":"Comme client fidèle"},{"id":"c","text":"Comme demandeur d’emploi"},{"id":"d","text":"Comme détenteur d’une part du capital concerné"}],"correctChoiceId":"d","explanation":"Le dividende est une distribution aux associés ou actionnaires. Il est lié à la détention du capital.","nuance":"Tous les salariés ne détiennent pas des actions de leur employeur.","sources":[{"publisher":"Ministère de l’Économie","title":"Dictionnaire de l’économie : action et dividendes","url":"https://www.economie.gouv.fr/facileco/dico-de-leco","checkedAt":"2026-10-23"}]},{"id":"q029-2","prompt":"Un salarié possède aussi des actions de son entreprise. Peut-il recevoir des dividendes ?","choices":[{"id":"a","text":"Oui, mais son salaire devient alors un dividende"},{"id":"b","text":"Oui, même si aucune distribution n’est décidée"},{"id":"c","text":"Oui, en sa qualité d’actionnaire si une distribution intervient"},{"id":"d","text":"Non, le salariat interdit les actions"}],"correctChoiceId":"c","explanation":"La même personne peut être salariée et actionnaire. Ses revenus relèvent alors de deux qualités distinctes.","nuance":"Détenir une action ne garantit pas un dividende à chaque exercice.","sources":[{"publisher":"Ministère de l’Économie","title":"Dictionnaire de l’économie : action et dividendes","url":"https://www.economie.gouv.fr/facileco/dico-de-leco","checkedAt":"2026-10-23"}]},{"id":"q029-3","prompt":"Quelle comparaison évite de confondre salaire et dividende ?","choices":[{"id":"a","text":"Comparer seulement les intitulés bancaires"},{"id":"b","text":"Identifier ce qui rémunère le travail et ce qui revient au capital"},{"id":"c","text":"Additionner tous les versements sous le mot salaire"},{"id":"d","text":"Appeler dividende toute prime"}],"correctChoiceId":"b","explanation":"Le salaire rémunère le travail salarié ; le dividende est attaché au capital détenu. Le destinataire peut parfois être la même personne.","nuance":"Cette distinction ne tranche pas le débat sur le partage de la valeur.","sources":[{"publisher":"Ministère de l’Économie","title":"Dictionnaire de l’économie : action et dividendes","url":"https://www.economie.gouv.fr/facileco/dico-de-leco","checkedAt":"2026-10-23"}]}]}','2026-10-23T12:00:00.000Z');
