INSERT OR IGNORE INTO quizzes(id,slug,category_id,title,outline,current_version,position) VALUES ('q031','les-chomeurs-ne-veulent-pas-travailler','travail','Les chômeurs ne veulent pas travailler','["Comment définit-on statistiquement un chômeur ?","Quelles démarches sont prises en compte ?","Un chiffre national révèle-t-il une motivation individuelle ?"]',NULL,30);
INSERT OR IGNORE INTO quiz_versions(quiz_id,version,body,published_at) VALUES ('q031',1,'{"title":"Les chômeurs ne veulent pas travailler","intro":"Avant de discuter des comportements, regardons ce que mesure réellement le chômage au sens du BIT.","questions":[{"id":"q031-1","prompt":"Quelle combinaison correspond à la définition statistique du chômage au sens du BIT ?","choices":[{"id":"a","text":"Toutes les personnes de plus de 60 ans"},{"id":"b","text":"Sans emploi, disponible et en recherche active, ou emploi déjà trouvé débutant prochainement"},{"id":"c","text":"Toute personne qui ne travaille pas, sans autre condition"},{"id":"d","text":"Uniquement les personnes indemnisées"}],"correctChoiceId":"b","explanation":"La définition combine l’absence d’emploi, la disponibilité et la recherche, avec le cas d’un emploi déjà trouvé qui commence prochainement.","nuance":"Il s’agit d’une définition statistique, pas d’une évaluation morale.","sources":[{"publisher":"Insee","title":"Chômeur au sens du BIT","url":"https://www.insee.fr/fr/metadonnees/definition/c1129","checkedAt":"2026-10-23"}]},{"id":"q031-2","prompt":"Faut-il obligatoirement recevoir une allocation pour être chômeur au sens du BIT ?","choices":[{"id":"a","text":"Non, l’indemnisation ne fait pas partie de ces critères"},{"id":"b","text":"Oui, toujours"},{"id":"c","text":"Oui, au moins le SMIC"},{"id":"d","text":"Uniquement en fin d’année"}],"correctChoiceId":"a","explanation":"Les critères du BIT ne comportent pas de condition de versement d’une allocation.","nuance":"Les droits à indemnisation suivent des règles distinctes.","sources":[{"publisher":"Insee","title":"Chômeur au sens du BIT","url":"https://www.insee.fr/fr/metadonnees/definition/c1129","checkedAt":"2026-10-23"}]},{"id":"q031-3","prompt":"Une personne sans emploi mais indisponible pour travailler immédiatement est-elle automatiquement comptée au chômage BIT ?","choices":[{"id":"a","text":"Oui, toute absence d’emploi suffit"},{"id":"b","text":"Oui, si elle possède un diplôme"},{"id":"c","text":"Non, uniquement à cause de son âge"},{"id":"d","text":"Non, la disponibilité fait partie des conditions"}],"correctChoiceId":"d","explanation":"La définition demande une disponibilité pour prendre un emploi dans les deux semaines. L’absence d’emploi seule ne suffit pas.","nuance":"Ne pas être classé au chômage BIT ne signifie pas forcément ne pas souhaiter travailler.","sources":[{"publisher":"Insee","title":"Chômeur au sens du BIT","url":"https://www.insee.fr/fr/metadonnees/definition/c1129","checkedAt":"2026-10-23"}]}]}','2026-10-23T12:00:00.000Z');
