INSERT OR IGNORE INTO quizzes(id,slug,category_id,title,outline,current_version,position) VALUES ('q036','mes-cotisations-sont-mises-de-cote-pour-ma-retraite','retraites','Mes cotisations sont mises de côté pour ma retraite','["Comment fonctionne la répartition ?","Que financent les cotisations actuelles ?","Quelle différence avec la capitalisation ?"]',NULL,35);
INSERT OR IGNORE INTO quiz_versions(quiz_id,version,body,published_at) VALUES ('q036',1,'{"title":"Mes cotisations sont mises de côté pour ma retraite","intro":"Comprendre ce que financent les cotisations et ce que représentent les droits acquis.","questions":[{"id":"q036-1","prompt":"Dans un régime par répartition, les cotisations actuelles servent principalement à quoi ?","choices":[{"id":"a","text":"Payer les pensions actuelles"},{"id":"b","text":"Remplir un compte personnel bloqué au nom de chaque cotisant"},{"id":"c","text":"Acheter automatiquement un logement à chaque retraité"},{"id":"d","text":"Rembourser uniquement la dette militaire"}],"correctChoiceId":"a","explanation":"La répartition organise un transfert des actifs vers les retraités actuels. Les cotisants acquièrent des droits pour leur propre retraite.","nuance":"Acquérir des droits n’est pas identique à mettre chaque euro sur un compte personnel.","sources":[{"publisher":"Ministère du Travail","title":"Le système et les régimes de retraite","url":"https://travail-emploi.gouv.fr/retraite","checkedAt":"2026-10-23"}]},{"id":"q036-2","prompt":"Quel énoncé décrit le mieux les droits à retraite ?","choices":[{"id":"a","text":"Une cagnotte individuelle contenant exactement toutes les cotisations"},{"id":"b","text":"Une promesse de récupérer exactement le même nombre d’euros"},{"id":"c","text":"Un placement garanti identique pour tous"},{"id":"d","text":"Des droits calculés selon les règles du régime"}],"correctChoiceId":"d","explanation":"Les pensions sont calculées selon les règles applicables, notamment la carrière et les revenus. Les droits ne sont pas un simple solde bancaire personnel.","nuance":"Le système comporte aussi des mécanismes de solidarité.","sources":[{"publisher":"Ministère du Travail","title":"Le système et les régimes de retraite","url":"https://travail-emploi.gouv.fr/retraite","checkedAt":"2026-10-23"}]},{"id":"q036-3","prompt":"Un régime par répartition peut-il disposer de réserves financières ?","choices":[{"id":"a","text":"Oui, donc il devient forcément entièrement par capitalisation"},{"id":"b","text":"Non, aucune caisse ne peut détenir d’actifs"},{"id":"c","text":"Oui, des réserves peuvent compléter son fonctionnement"},{"id":"d","text":"Non, c’est impossible par définition"}],"correctChoiceId":"c","explanation":"Le COR documente les réserves de plusieurs régimes par répartition. Leur existence peut aider à lisser des déséquilibres dans le temps.","nuance":"Réserves collectives et épargne individuelle en capitalisation ne sont pas équivalentes.","sources":[{"publisher":"Conseil d’orientation des retraites","title":"Répartition, réserves et capitalisation","url":"https://www.cor-retraites.fr/reunions-du-cor/repartition-reserves-capitalisation-quels-enjeux-pour-retraites","checkedAt":"2026-10-23"}]}]}','2026-10-23T12:00:00.000Z');
