INSERT OR IGNORE INTO quizzes(id,slug,category_id,title,outline,current_version,position) VALUES ('q042','immigre-et-etranger-c-est-la-meme-chose','accueil','Immigré et étranger, c’est la même chose','["Comment définit-on ces catégories ?","Une personne immigrée peut-elle être française ?","Une personne étrangère peut-elle être née en France ?"]',NULL,41);
INSERT OR IGNORE INTO quiz_versions(quiz_id,version,body,published_at) VALUES ('q042',1,'{"title":"Immigré et étranger, c’est la même chose","intro":"Deux catégories souvent confondues. Les définitions utilisées ici sont celles de l’Insee.","questions":[{"id":"q042-1","prompt":"Selon l’Insee, une personne immigrée résidant en France est une personne…","choices":[{"id":"a","text":"Qui ne parle pas français"},{"id":"b","text":"Qui voyage à l’étranger"},{"id":"c","text":"Née étrangère à l’étranger"},{"id":"d","text":"Née en France de parents étrangers"}],"correctChoiceId":"c","explanation":"La définition combine le lieu de naissance à l’étranger et la nationalité étrangère à la naissance.","nuance":"Elle ne dépend pas de la langue parlée ni des convictions de la personne.","sources":[{"publisher":"Insee","title":"Définition : immigré","url":"https://www.insee.fr/fr/metadonnees/definition/c1328","checkedAt":"2026-10-23"}]},{"id":"q042-2","prompt":"Une personne née étrangère à l’étranger et devenue française reste-t-elle immigrée au sens statistique ?","choices":[{"id":"a","text":"Uniquement si elle vit à Paris"},{"id":"b","text":"Oui"},{"id":"c","text":"Non, elle ne l’a jamais été"},{"id":"d","text":"Uniquement si elle possède deux passeports"}],"correctChoiceId":"b","explanation":"L’acquisition de la nationalité française ne modifie pas le lieu et la nationalité de naissance. Elle reste donc immigrée au sens de cette définition.","nuance":"Elle n’est plus étrangère si elle possède la nationalité française.","sources":[{"publisher":"Insee","title":"Définition : immigré","url":"https://www.insee.fr/fr/metadonnees/definition/c1328","checkedAt":"2026-10-23"},{"publisher":"Insee","title":"Définition : étranger","url":"https://www.insee.fr/fr/metadonnees/definition/c1198","checkedAt":"2026-10-23"}]},{"id":"q042-3","prompt":"Une personne née en France peut-elle être étrangère sans être immigrée ?","choices":[{"id":"a","text":"Oui"},{"id":"b","text":"Non, ces catégories sont identiques"},{"id":"c","text":"Seulement après 80 ans"},{"id":"d","text":"Seulement si elle travaille à l’étranger"}],"correctChoiceId":"a","explanation":"Une personne résidant en France sans nationalité française peut être née en France. Elle est alors étrangère mais ne répond pas à la définition d’immigré.","nuance":"Les règles d’acquisition de la nationalité constituent un autre sujet.","sources":[{"publisher":"Insee","title":"Définition : étranger","url":"https://www.insee.fr/fr/metadonnees/definition/c1198","checkedAt":"2026-10-23"}]}]}','2026-10-23T12:00:00.000Z');
