INSERT OR IGNORE INTO quiz_versions(quiz_id,version,body,published_at) VALUES ('q096',1,'{"title":"Le vote blanc compte comme un vote pour un candidat","intro":"Comprendre comment les bulletins sont classés et comment les résultats sont calculés.","questions":[{"id":"q096-1","prompt":"Une enveloppe vide déposée dans l’urne correspond à quel type de vote ?","choices":[{"id":"a","text":"Un vote blanc"},{"id":"b","text":"Un vote pour le candidat arrivé premier"},{"id":"c","text":"Une abstention"},{"id":"d","text":"Un vote pour tous les candidats"}],"correctChoiceId":"a","explanation":"L’enveloppe vide est comptabilisée comme vote blanc. Elle marque une participation sans choix d’un candidat.","nuance":"Ce quiz décrit les règles françaises exposées par la DILA.","sources":[{"publisher":"Vie publique — DILA","title":"Vote blanc, vote nul : quelles différences ?","url":"https://www.vie-publique.fr/fiches/23931-vote-blanc-vote-nul-quelles-differences","checkedAt":"2026-10-23"}]},{"id":"q096-2","prompt":"Les votes blancs entrent-ils dans les suffrages exprimés ?","choices":[{"id":"a","text":"Oui, au bénéfice du gagnant"},{"id":"b","text":"Oui, divisés entre les candidats"},{"id":"c","text":"Oui, uniquement au second tour"},{"id":"d","text":"Non"}],"correctChoiceId":"d","explanation":"Ils sont comptés séparément, mais ne font pas partie des suffrages exprimés utilisés pour les pourcentages des candidats.","nuance":"Être décompté ne signifie donc pas être inclus dans ce dénominateur.","sources":[{"publisher":"Vie publique — DILA","title":"Vote blanc, vote nul : quelles différences ?","url":"https://www.vie-publique.fr/fiches/23931-vote-blanc-vote-nul-quelles-differences","checkedAt":"2026-10-23"}]},{"id":"q096-3","prompt":"Quelle différence entre vote blanc et abstention ?","choices":[{"id":"a","text":"Le vote blanc vaut deux abstentions"},{"id":"b","text":"L’abstention est attribuée à un candidat"},{"id":"c","text":"Voter blanc implique de participer au vote ; s’abstenir signifie ne pas voter"},{"id":"d","text":"Aucune, ils sont classés ensemble"}],"correctChoiceId":"c","explanation":"Le vote blanc et l’abstention correspondent à deux comportements et deux catégories distincts.","nuance":"On ne peut pas déduire les motivations individuelles de ces seules catégories.","sources":[{"publisher":"Vie publique — DILA","title":"Vote blanc, vote nul : quelles différences ?","url":"https://www.vie-publique.fr/fiches/23931-vote-blanc-vote-nul-quelles-differences","checkedAt":"2026-10-23"}]}]}','2026-10-23T12:00:00.000Z');
