INSERT OR IGNORE INTO quizzes(id,slug,category_id,title,outline,current_version,position) VALUES ('q099','un-candidat-a-30-est-soutenu-par-30-des-francais','elections','Un candidat à 30 % est soutenu par 30 % des Français','["Quel est le dénominateur ?","Quelle différence entre inscrits et exprimés ?","Comment recalculer sur une autre population ?"]',NULL,98);
INSERT OR IGNORE INTO quiz_versions(quiz_id,version,body,published_at) VALUES ('q099',1,'{"title":"Un candidat à 30 % est soutenu par 30 % des Français","intro":"Un pourcentage ne signifie rien sans sa population de référence. Exercices fictifs, pas résultats d’une élection réelle.","questions":[{"id":"q099-1","prompt":"Dans « 30 % des suffrages exprimés », quel est le dénominateur ?","choices":[{"id":"a","text":"Tous les inscrits, automatiquement"},{"id":"b","text":"Les suffrages exprimés, pas toute la population"},{"id":"c","text":"Tous les habitants, enfants compris"},{"id":"d","text":"Tous les abstentionnistes"}],"correctChoiceId":"b","explanation":"Le pourcentage se rapporte aux suffrages exprimés. Les votes blancs et nuls n’y sont pas inclus.","nuance":"Les personnes non inscrites ne figurent pas non plus dans ce dénominateur.","sources":[{"publisher":"Ministère de l’Intérieur","title":"Qu’est-ce que le vote blanc ?","url":"https://www.interieur.gouv.fr/archive/qu-est-ce-que-le-vote-blanc","checkedAt":"2026-10-23"}]},{"id":"q099-2","prompt":"Sur 1 000 inscrits, 600 suffrages sont exprimés. Un candidat en obtient 180. Quelle part des inscrits cela représente-t-il ?","choices":[{"id":"a","text":"18 %"},{"id":"b","text":"30 %"},{"id":"c","text":"60 %"},{"id":"d","text":"180 %"}],"correctChoiceId":"a","explanation":"180 divisé par 1 000 donne 18 %. Le même candidat a 30 % des 600 suffrages exprimés.","nuance":"Exemple arithmétique fictif : les deux pourcentages répondent à des questions différentes.","sources":[{"publisher":"Ministère de l’Intérieur","title":"Qu’est-ce que le vote blanc ?","url":"https://www.interieur.gouv.fr/archive/qu-est-ce-que-le-vote-blanc","checkedAt":"2026-10-23"}]},{"id":"q099-3","prompt":"Peut-on attribuer une opinion précise à tous ceux qui n’ont pas voté pour ce candidat ?","choices":[{"id":"a","text":"Oui, ils pensent tous exactement la même chose"},{"id":"b","text":"Oui, ils soutiennent tous le deuxième"},{"id":"c","text":"Oui, ils ont tous voté blanc"},{"id":"d","text":"Non, les raisons et comportements peuvent être différents"}],"correctChoiceId":"d","explanation":"Les catégories du vote distinguent participation, abstention et bulletins. Elles ne révèlent pas à elles seules toutes les motivations.","nuance":"Un résultat électoral ne remplace pas une enquête sur les opinions.","sources":[{"publisher":"Ministère de l’Intérieur","title":"Qu’est-ce que le vote blanc ?","url":"https://www.interieur.gouv.fr/archive/qu-est-ce-que-le-vote-blanc","checkedAt":"2026-10-23"}]}]}','2026-10-23T12:00:00.000Z');
UPDATE quizzes SET current_version=1 WHERE id='q099' AND current_version IS NULL;
